com.system76.Popsicle : apps/com.system76.Popsicle.svg   # Gravador USB Popsicle — pirulito
input-keyboard : apps/input-keyboard.svg   # Input Method [upstream]
org.kde.krita : apps/org.kde.krita.svg   # Krita — varinha (variação)
menulibre : apps/menulibre.svg   # Menu Editor — pergaminho
nyx : apps/nyx.svg   # Nyx [arte-propria]
md.obsidian.Obsidian : apps/md.obsidian.Obsidian.svg   # Obsidian [alias-heuristico]
org.onlyoffice.desktopeditors : apps/org.onlyoffice.desktopeditors.svg   # ONLYOFFICE — livro
org.qbittorrent.qBittorrent : apps/org.qbittorrent.qBittorrent.svg   # qBittorrent [alias-heuristico]
rlogo_icon : apps/rlogo_icon.svg   # R — livro de feitiços
steam : apps/steam.svg   # Steam [current-nome]
org.telegram.desktop : apps/org.telegram.desktop.svg   # Telegram [alias-heuristico]
io.github.flattool.Warehouse : apps/io.github.flattool.Warehouse.svg   # Warehouse — edifício

# A CÂMERA VESTE O DESENHO DO guvcview, E ISSO É ESCOLHA DELE — 16/09/2026
#   "a camera tem que ter o guvcview.svg". O guvcview saiu da máquina na
#   limpeza de 15/09; o desenho resgatado dele ficou, sem app para vestir. A
#   Camera do COSMIC estava de fábrica. Um desenho órfão e um app sem desenho.
io.github.cosmic_utils.camera : apps/guvcview.svg   # Câmera — o desenho do guvcview
#   ^ COPIADO de assets/icones/resgatados/guvcview.svg em 17/09/2026. A entrada
#     apontava para o acervo 'resgatados' do núcleo, de fora do pack — o que
#     funcionava enquanto o Dracula morava dentro do repositório e deixa de
#     funcionar no minuto em que alguém clona só o pack. Um pack precisa ser
#     AUTOCONTIDO; reusar arte do núcleo é copiar, respeitando a licença dela.

# O WATERFOX VESTE O FIREFOX-DRACULA — 23/09/2026, P28
#   A linha estava lá embaixo, em "sem desenho ainda", como
#   `# net.waterfox.waterfox : ?`. O ícone que aparecia era a raposa roxa da
#   lua, instalada pelo `apps-resgatados.map` do motor — e a decisão que abriu a
#   P28 foi trocá-la pelo Firefox do upstream Dracula. O desenho foi COPIADO
#   para `apps/` (regra 5) e a origem, a licença, a data e o sha256 estão no
#   `PROCEDENCIA.md` deste pack; por que o ramo `circle` e não o `main`, também.
#   A linha saiu do `apps-resgatados.map` no mesmo commit: os dois escrevem em
#   `scalable/apps`, e um nome com duas fontes ali é o último instalador que
#   rodar vencendo calado — o que a regra 1 ("um nome, uma fonte") proíbe.
#   A raposa continua em `assets/icones/resgatados/`, como alternativa.
net.waterfox.waterfox : apps/net.waterfox.waterfox.svg   # Waterfox — o Firefox do dracula-icons (circle)

